const model = 'qwen/qwen3.5-flash-02-23@reasoning_effort=none';
const PROMPT_VERSION = 'mnn_qwen_web_search_v1';

const SYSTEM_PROMPT = `Ты являешься верификатором MNN для российских аптечных товаров.\n\nТвоя задача — использовать web search и определить международное непатентованное наименование\nили основные действующие вещества только для конкретного лекарственного препарата.\n\nПравила:\n\n1. Используй результаты веб-поиска, а не только внутренние знания.\n2. Сначала проверь идентичность товара.\n3. Возвращай MNN только если найденный источник относится именно к этому товару.\n4. Не подменяй MNN терапевтическим классом.\n5. Не угадывай MNN по памяти.\n6. Если источники противоречат — mnn=null и status=conflict|not_found.\n7. Комбинации через \" + \" только если прямо указаны в источнике.\n8. Ответ только валидный JSON.`;

const row = {
  product_id: 'smoke-nurofen',
  run_id: '',
  mnn_test_run_id: $execution.id || ('n8n-' + Date.now()),
  product_kind: 'drug',
  normalized_text: 'НУРОФЕН ТАБЛ. П/О 200МГ №20',
  attr_brand: 'Нурофен',
  attr_dosage_form: 'таблетки',
  attr_dosage: '200 мг',
  attr_administration_route: '',
  semantic_explanation: '',
  catalog_mnn_for_comparison: 'Ибупрофен',
  catalog_source_summary: 'smoke',
};

const user = `Определи MNN для следующего товара через web search.\n\nИсходный товар:\n- product_id: ${row.product_id}\n- normalized_text: ${row.normalized_text}\n- бренд / торговое наименование: ${row.attr_brand}\n- лекарственная форма: ${row.attr_dosage_form}\n- дозировка / концентрация: ${row.attr_dosage}\n- путь введения: —\n- дополнительный семантический контекст: —\n\nПриоритетно ищи в русскоязычных источниках (Ютека, Еаптека, Apteka.ru, Здравсити).\n\nВерни строго JSON с полями mnn, status, model_confidence, short_explanation, identity_match, used_source_indexes, evidence.`;

const searchPrompt = 'Нурофен таблетки 200 мг';

return [{
  json: {
    ...row,
    qwen_search_prompt_version: PROMPT_VERSION,
    qwen_search_query: searchPrompt,
    qwen_search_model: model,
    qwen_search_provider: 'polza',
    qwen_search_enabled: true,
    _qwen_started_ms: Date.now(),
    polza_request_body: {
      model,
      temperature: 0.1,
      max_tokens: 900,
      messages: [
        { role: 'system', content: SYSTEM_PROMPT },
        { role: 'user', content: user },
      ],
      plugins: [
        {
          id: 'web',
          engine: 'exa',
          max_results: 5,
          search_prompt: searchPrompt,
        },
      ],
    },
  },
}];

const prep = $('MNN Qwen Search — Build Prompt').all();
return items.map((item, index) => {
  const base = { ...(prep[index] || prep[0] || {}).json, ...(item.json || {}) };
  const err = item.json && (item.json.error || item.json.message);
  // HTTP node puts response body in json; on failure may nest differently
  const looksLikeCompletion = Array.isArray((item.json || {}).choices);
  const out = {
    ...base,
    polza_raw: looksLikeCompletion ? item.json : null,
    qwen_http_error: looksLikeCompletion ? null : (err || (!looksLikeCompletion ? JSON.stringify(item.json).slice(0, 300) : null)),
    qwen_search_latency_ms: base._qwen_started_ms ? (Date.now() - Number(base._qwen_started_ms)) : null,
  };
  delete out.polza_request_body;
  return { json: out, pairedItem: item.pairedItem ?? { item: index } };
});

const PROMPT_VERSION = 'mnn_qwen_web_search_v1';
const ALLOWED_STATUS = new Set(['found', 'not_found', 'conflict']);

function extractJsonString(value) {
  if (value === null || value === undefined) return null;
  if (typeof value === 'object') return JSON.stringify(value);
  let text = String(value).trim();
  const fence = text.match(/^```(?:json)?\s*\n?([\s\S]+?)\n?```\s*$/i);
  if (fence) text = fence[1].trim();
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start >= 0 && end > start) text = text.slice(start, end + 1);
  return text;
}

function extractAnnotations(api) {
  const sources = [];
  if (!api || typeof api !== 'object') return sources;
  const msg = (((api.choices || [])[0] || {}).message) || {};
  const anns = msg.annotations || [];
  if (Array.isArray(anns)) {
    anns.forEach((a, i) => {
      const uc = (a && a.url_citation) || a || {};
      const url = uc.url || a.url || null;
      if (!url) return;
      sources.push({ index: i + 1, url: String(url), title: uc.title || null, snippet: uc.content || null });
    });
  }
  return sources;
}

function normalizeMnnLight(s) {
  if (s === null || s === undefined) return null;
  let t = String(s).trim();
  if (!t || t.toLowerCase() === 'null') return null;
  return t.replace(/\*/g, ' ').replace(/\s+/g, ' ').trim() || null;
}

function foldKey(s) {
  return String(s || '').toLowerCase().replace(/ё/g, 'е').replace(/\s+/g, ' ').trim()
    .replace(/\s*[+,;/|]\s*/g, '+').split('+').filter(Boolean).sort().join('+');
}

return items.map((item, index) => {
  const j = { ...(item.json || {}) };
  const api = j.polza_raw || null;
  const apiError = j.qwen_http_error || null;
  const base = { ...j };
  delete base.polza_raw; delete base.qwen_http_error; delete base._qwen_started_ms;

  if (apiError) {
    return { json: { ...base, qwen_search_status: 'api_error', qwen_search_mnn: null, qwen_search_source_count: 0, qwen_search_sources_json: '[]', qwen_search_error: String(apiError).slice(0, 500), qwen_vs_catalog_status: 'qwen_api_error', qwen_vs_catalog_comment: 'HTTP/API error' }, pairedItem: item.pairedItem ?? { item: index } };
  }

  const sources = extractAnnotations(api);
  const content = (((api || {}).choices || [{}])[0].message || {}).content;
  let parsed = null;
  try {
    const raw = extractJsonString(content);
    if (raw) parsed = JSON.parse(raw);
  } catch (e) {
    parsed = null;
  }
  const primary = sources[0] || null;

  if (!sources.length) {
    return { json: { ...base, qwen_search_status: 'search_not_confirmed', qwen_search_mnn: null, qwen_search_source_count: 0, qwen_search_sources_json: '[]', qwen_search_error: 'no_source_annotations', qwen_search_short_explanation: (parsed && parsed.short_explanation) || 'нет annotations', qwen_vs_catalog_status: 'qwen_search_not_confirmed', qwen_vs_catalog_comment: 'web search not confirmed' }, pairedItem: item.pairedItem ?? { item: index } };
  }

  let status = parsed ? String(parsed.status || '').trim() : 'not_found';
  if (!ALLOWED_STATUS.has(status)) status = 'not_found';
  let mnn = parsed ? normalizeMnnLight(parsed.mnn) : null;
  if (status !== 'found') mnn = null;
  if (status === 'found' && !mnn) status = 'not_found';

  const catalog = String(base.catalog_mnn_for_comparison || '').trim();
  const qwen = mnn || '';
  let vs = 'both_empty';
  let comment = '';
  if (!catalog && !qwen) { vs = 'both_empty'; comment = 'оба пусты'; }
  else if (!catalog && qwen) { vs = 'qwen_only'; comment = 'только Qwen'; }
  else if (catalog && !qwen) { vs = 'catalog_only'; comment = 'только каталог'; }
  else if (catalog === qwen) { vs = 'exact_match'; comment = 'exact'; }
  else if (foldKey(catalog) === foldKey(qwen)) { vs = 'normalized_match'; comment = 'normalized'; }
  else { vs = 'conflict'; comment = 'различаются'; }

  return {
    json: {
      ...base,
      qwen_search_prompt_version: PROMPT_VERSION,
      qwen_search_status: status,
      qwen_search_mnn: mnn,
      qwen_search_model_confidence: parsed && typeof parsed.model_confidence === 'number' ? parsed.model_confidence : null,
      qwen_search_short_explanation: parsed ? parsed.short_explanation : null,
      qwen_search_evidence: parsed ? parsed.evidence : null,
      qwen_search_source_count: sources.length,
      qwen_search_sources_json: JSON.stringify(sources),
      qwen_search_source_url_primary: primary ? primary.url : null,
      qwen_search_source_title_primary: primary ? primary.title : null,
      qwen_search_error: null,
      qwen_vs_catalog_status: vs,
      qwen_vs_catalog_comment: comment,
    },
    pairedItem: item.pairedItem ?? { item: index },
  };
});
